import React, { useState, useEffect, useRef } from 'react';
import { fetchApplicant } from './api/apiClient';
import './index.css';

const ApplicantDashboard = ({ applicantId, token }) => {
  const [applicant, setApplicant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const pollTimer = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const loadApplicant = async () => {
      if (!applicant) setLoading(true);
      setError('');
      try {
        const res = await fetchApplicant(applicantId, token);
        if (cancelled) return;
        setApplicant(res.data);
        // If still processing, poll again in 3s
        const status = (res.data?.status || '').toString();
        if (status === 'submitted' || status === 'processing') {
          pollTimer.current = setTimeout(loadApplicant, 3000);
        }
      } catch (err) {
        if (!cancelled) setError('Failed to load applicant data.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    loadApplicant();
    return () => {
      cancelled = true;
      if (pollTimer.current) clearTimeout(pollTimer.current);
    };
  }, [applicantId, token]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div style={{ color: 'red' }}>{error}</div>;
  if (!applicant) return <div>No applicant data found.</div>;

  return (
    <div className="dashboard-container">
      <h2>Applicant Dashboard</h2>
      <p>Welcome, {applicant.name}! Here is your submitted information and our analysis.</p>
      <p><strong>Status:</strong> {applicant.status || 'unknown'}</p>
      
      <div className="applicant-details">
        <h3>Your Information</h3>
        <p><strong>Email:</strong> {applicant.email}</p>
        <p><strong>LinkedIn:</strong> <a href={applicant.linkedin_url} target="_blank" rel="noopener noreferrer">Profile</a></p>
        
        <h3>Our Analysis</h3>
        <p><strong>Overall Rating:</strong> {applicant.insights?.rating || 'Not yet rated'}</p>
        <p><strong>Experience:</strong> {applicant.insights?.experience_years || 'Not yet calculated'} years</p>
        <p><strong>Sentiment Score:</strong> {typeof applicant.insights?.sentiment_score === 'number' ? applicant.insights.sentiment_score.toFixed(2) : 'N/A'}</p>
        <p><strong>Activity Score:</strong> {typeof applicant.insights?.activity_score === 'number' ? applicant.insights.activity_score.toFixed(2) : 'N/A'}</p>
        <p><strong>Summary:</strong> {applicant.insights?.summary || 'No summary available.'}</p>
        {Array.isArray(applicant.insights?.top_endorsed_skills) && applicant.insights.top_endorsed_skills.length > 0 && (
          <>
            <h4>Top Endorsed Skills:</h4>
            <ul>
              {applicant.insights.top_endorsed_skills.map((s, idx) => (
                <li key={idx}>{typeof s === 'string' ? s : JSON.stringify(s)}</li>
              ))}
            </ul>
          </>
        )}
        {Array.isArray(applicant.insights?.projects) && applicant.insights.projects.length > 0 && (
          <>
            <h4>Projects:</h4>
            <ul>
              {applicant.insights.projects.map((p, idx) => (
                <li key={idx}>{typeof p === 'string' ? p : (p?.name || JSON.stringify(p))}</li>
              ))}
            </ul>
          </>
        )}
        
        <h4>Extracted Skills:</h4>
        {applicant.resume?.structured_data?.skills ? (
          <ul>
            {applicant.resume.structured_data.skills.map((skill, index) => (
              <li key={index}>{skill}</li>
            ))}
          </ul>
        ) : <p>No skills extracted.</p>}
      </div>
    </div>
  );
};

export default ApplicantDashboard;
